#dialogue { position: absolute; bottom: 200px; left: 50%; transform: translateX(-50%); width: 640px; background: rgba(0,0,0,.72); border-radius: 8px; padding: 12px 18px; font-size: 17px; display: none; }
#dialogue-speaker { font-weight: 900; color: #ffd700; margin-right: 8px; }

/* ---------- Screens ---------- */
#start-screen, #pause-screen, #end-screen {
  position: absolute; inset: 0; display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  background: linear-gradient(160deg, rgba(8,20,40,.88), rgba(60,10,40,.82));
  text-align: center;
}
.title-kicker { font-size: 18px; letter-spacing: 8px; color: #ffd700; }
.title-block h1 {
  font-size: 84px; font-weight: 900; letter-spacing: 4px; line-height: 1;
  background: linear-gradient(180deg, #ffe259, #ffa751, #ff5e62);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  text-shadow: none; margin: 8px 0;
}
.title-sub { font-size: 17px; letter-spacing: 6px; color: #cfe8ff; }
.menu-buttons { display: flex; flex-direction: column; gap: 12px; margin-top: 34px; }
.menu-buttons button {
  font-family: inherit; font-size: 19px; font-weight: 800; letter-spacing: 2px;
  color: #fff; background: rgba(255,255,255,.08); border: 2px solid rgba(255,255,255,.45);
  padding: 12px 46px; cursor: pointer; border-radius: 4px; transition: all .15s;
}
.menu-buttons button:hover { background: #ffd700; color: #111; border-color: #ffd700; }
#controls-panel { margin-top: 22px; font-size: 15px; line-height: 1.9; color: #dfeaff; background: rgba(0,0,0,.4); padding: 12px 26px; border-radius: 8px; }
.title-foot { position: absolute; bottom: 18px; font-size: 12px; color: rgba(255,255,255,.55); }
#pause-screen h2, #end-screen h2 { font-size: 56px; font-weight: 900; letter-spacing: 6px; }
#end-title { color: #ff3b30; }
#end-sub { font-size: 18px; color: #ddd; margin-top: 8px; }
#pause-stats { margin-top: 24px; font-size: 16px; line-height: 1.8; color: #cfe8ff; }
#mission-complete {
  position: absolute; top: 34%; left: 50%; transform: translate(-50%, -50%);
  text-align: center; background: rgba(0,0,0,.78); padding: 28px 60px; border-radius: 10px;
  border: 2px solid #ffd700;
}
.mc-title { font-size: 34px; font-weight: 900; color: #7cf29c; letter-spacing: 3px; }
#mc-name { font-size: 20px; margin-top: 8px; }
#mc-reward { font-size: 24px; font-weight: 800; color: #ffd700; margin-top: 6px; }
